const $=s=>document.querySelector(s);const ns='http://www.w3.org/2000/svg';const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);function f(n,d){const g=gcd(n,d);return n===0?'0':d/g===1?String(n/g).replace('-','−'):`${String(n/g).replace('-','−')}/${d/g}`}const storage={get(k){try{return localStorage.getItem('fondasi-divide-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-divide-'+k,v);return true}catch{return false}}};const ex=[{a:1,b:1,c:1,d:2},{a:3,b:4,c:1,d:4},{a:3,b:4,c:1,d:2},{a:1,b:2,c:3,d:4},{a:3,b:2,c:1,d:4},{a:3,b:4,c:3,d:2}];
function svg(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;$('#tape-drawing').append(e);return e}function update(){const e=ex[Number($('#example').value)],n=e.a*e.d,d=e.b*e.c,g=gcd(n,d),N=n/g,D=d/g,full=Math.floor(N/D),rem=N%D,groups=Math.ceil(N/D),amount=e.a/e.b,size=e.c/e.d,max=groups*size,w=540/max;$('#tape-drawing').replaceChildren();svg('rect',{x:30,y:65,width:540,height:55,fill:'#f8f7f2',stroke:'#244d40'});for(let i=0;i<groups;i++){const start=i*size,fill=Math.max(0,Math.min(size,amount-start));if(fill>0)svg('rect',{x:30+start*w,y:65,width:fill*w,height:55,fill:i%2?'#e4bcaa':'#b9ceae'});svg('line',{x1:30+start*w,x2:30+start*w,y1:58,y2:128,stroke:'#244d40','stroke-width':2});svg('text',{x:30+(i+.5)*size*w,y:47,'text-anchor':'middle',class:'group-label'},`${i+1}`)}svg('line',{x1:570,x2:570,y1:58,y2:128,stroke:'#244d40','stroke-width':2});svg('text',{x:30,y:165,'text-anchor':'start'},'0');svg('text',{x:570,y:165,'text-anchor':'end'},`${f(groups*e.c,e.d)} m`);const end=30+amount*w;svg('path',{d:`M${end} 132v12`,stroke:'#a75b3e','stroke-width':3});svg('text',{x:Math.max(90,Math.min(510,end)),y:195,'text-anchor':'middle'},`tersedia: ${f(e.a,e.b)} m`);$('#tape').setAttribute('aria-label',`Tersedia ${f(e.a,e.b)} meter. Ukuran kelompok ${f(e.c,e.d)} meter. Ada ${full} kelompok penuh${rem?` dan ${rem}/${D} kelompok lagi`:''}.`);$('#given').textContent=`Pita tersedia: ${f(e.a,e.b)} meter. Ukuran satu kelompok: ${f(e.c,e.d)} meter. Angka di atas bingkai menandai urutan kelompok; warna menunjukkan pita tersedia.`;$('#equation').textContent=`${f(e.a,e.b)} ÷ ${f(e.c,e.d)} = ${f(N,D)}`;$('#feedback').textContent=rem?`Ada ${full} kelompok penuh dan ${rem}/${D} kelompok lagi. ${full===0?'Seluruh pita belum mengisi satu kelompok penuh. ':''}Sisa ${f(e.a*e.d-full*e.c*e.b,e.b*e.d)} meter dibandingkan dengan ukuran satu kelompok, yaitu ${f(e.c,e.d)} meter. Jadi totalnya ${f(N,D)} kelompok.`:`Tepat ${full} kelompok penuh berukuran ${f(e.c,e.d)} meter muat dalam pita ${f(e.a,e.b)} meter. Tidak ada sisa.`;$('#check-product').textContent=`Periksa: ${f(N,D)} × ${f(e.c,e.d)} = ${f(e.a,e.b)}. Banyak kelompok × ukuran kelompok = panjang pita tersedia.`}$('#example').addEventListener('change',update);update();
$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=awal]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan terlebih dahulu.':v==='two'?'Tepat. Dua gelas berukuran setengah liter memuat satu liter: 2 × 1/2 = 1.':v==='half'?'Pembagian tidak selalu memperkecil. Dalam satu liter, ada dua kelompok setengah liter, jadi hasilnya 2 gelas.':'Satu liter menyatakan jumlah air. Yang dicari adalah banyak gelas berukuran setengah liter. Ada dua gelas.'});
const qs=[{t:'1 ÷ 1/2 = …',n:2,d:1,h:'Ada berapa bagian setengah dalam satu utuh?',why:'Ada 2 bagian. Periksa: 2 × 1/2 = 1.'},{t:'3/4 ÷ 1/4 = …',n:3,d:1,h:'Tiga seperempat memuat berapa kelompok seperempat?',why:'Ada 3 kelompok. Periksa: 3 × 1/4 = 3/4.'},{t:'3/4 ÷ 1/2 = …',n:3,d:2,h:'Kalikan 3/4 dengan kebalikan 1/2, yaitu 2.',why:'3/4 × 2 = 6/4 = 3/2. Satu kelompok penuh dan setengah kelompok lagi.'},{t:'2/3 ÷ 4/5 = …',n:5,d:6,h:'Kebalikan pembaginya adalah 5/4. Bilangan 2/3 tetap.',why:'2/3 × 5/4 = 10/12 = 5/6. Periksa: 5/6 × 4/5 = 2/3.'},{t:'0 ÷ 2/3 = …',n:0,d:1,h:'Pembaginya bukan nol. Berapa kelompok yang tersedia jika jumlah awal nol?',why:'Hasilnya 0. Periksa: 0 × 2/3 = 0.'},{t:'−1/2 ÷ 1/4 = …',n:-2,d:1,h:'Negatif dibagi positif hasilnya negatif. Kalikan dengan kebalikan pembagi.',why:'−1/2 × 4 = −2. Periksa: −2 × 1/4 = −1/2.'}];function parse(s){const m=s.trim().replace(/−/g,'-').match(/^([+-]?\d+)(?:\s*\/\s*([+-]?\d+))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]?Number(m[2]):1;return Number.isSafeInteger(n)&&Number.isSafeInteger(d)&&d!==0&&Math.abs(n)<=1000000&&Math.abs(d)<=1000000?{n,d}:null}const solved=new Set();function progress(){$('#progress').textContent=`${solved.size} dari 7 latihan telah dijawab dengan tepat.`}$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.t}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}, pecahan atau bilangan bulat</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="text" placeholder="misalnya 3/2" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.q),v=parse($('#answer'+i).value),q=qs[i],ok=v&&v.n*q.d===q.n*v.d;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=!v?'Tulis pecahan seperti 3/2 atau bilangan bulat seperti -2. Penyebut jawaban tidak boleh nol.':ok?'Tepat. '+q.why:'Belum tepat. Periksa pecahan yang menjadi pembagi. Kalikan jawabanmu dengan pembagi: apakah kembali ke bilangan awal?';if(ok)solved.add(i);progress()}));$('#check-zero').addEventListener('click',()=>{const v=document.querySelector('[name=zero]:checked')?.value,ok=v==='undefined';$('#zero-feedback').className='feedback '+(ok?'correct':'incorrect');$('#zero-feedback').textContent=!v?'Pilih satu jawaban dahulu.':ok?'Tepat. Tidak ada bilangan x yang memenuhi x × 0 = 1/2. Pembagian dengan nol tidak terdefinisi.':'Belum tepat. Hasil bagi seharusnya menghasilkan 1/2 saat dikalikan dengan 0. Adakah bilangan yang memenuhi?';if(ok)solved.add(6);progress()});$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum bisa disimpan. Salin jika ingin menyimpannya.'});function complete(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(storage.get('complete')==='yes')complete();$('#complete').addEventListener('click',()=>{const ok=storage.set('complete','yes');complete();$('#complete-note').textContent=ok?'Kemajuan tersimpan. Kamu dapat kembali berlatih kapan saja.':'Selesai. Kemajuan belum dapat disimpan pada peramban ini.'});
